      /**
       * 获取报告状态
       */
      async getReportStatus(reportId) {
        try {
          const response = await this.axiosInstance.get(`/reporting/reports/${reportId}`);
          console.log(`[Amazon API] \u62A5\u544A\u72B6\u6001\u54CD\u5E94:`, JSON.stringify(response.data, null, 2));
          return {
            status: response.data.status,
            url: response.data.url,
            failureReason: response.data.failureReason
          };
        } catch (error) {
          console.error(`[Amazon API] \u83B7\u53D6\u62A5\u544A\u72B6\u6001\u5931\u8D25:`, error.response?.data || error.message);
          throw error;
        }
      }
      /**
       * 下载报告数据
       */
      async downloadReport(url) {
        const response = await axios2.get(url, {
          responseType: "stream"
        });
        const zlib = await import("zlib");
        const { Readable } = await import("stream");
        return new Promise((resolve, reject) => {
          const chunks = [];
          let totalSize = 0;
          const MAX_SIZE = 500 * 1024 * 1024;
          const gunzip = zlib.createGunzip();
          response.data.pipe(gunzip).on("data", (chunk) => {
            totalSize += chunk.length;
            if (totalSize > MAX_SIZE) {
              gunzip.destroy();
              reject(new Error(`Report too large: ${totalSize} bytes exceeds ${MAX_SIZE} bytes limit`));
              return;
            }
            chunks.push(chunk);
          }).on("end", () => {
            try {
              const data = Buffer.concat(chunks).toString("utf-8");
              const result = JSON.parse(data);
              console.log(`[Amazon API] \u62A5\u544A\u89E3\u538B\u5B8C\u6210\uFF0C\u539F\u59CB\u5927\u5C0F: ${totalSize} bytes, \u6570\u636E\u6761\u6570: ${result?.length || 0}`);
              resolve(result);
            } catch (parseError) {
              reject(new Error(`Failed to parse report JSON: ${parseError.message}`));
            }
          }).on("error", (err) => {
            reject(new Error(`Failed to decompress report: ${err.message}`));
          });
        });
      }
      /**
       * 等待报告完成并下载
       */
      async waitAndDownloadReport(reportId, maxWaitMs = 9e5) {
        const startTime = Date.now();
        console.log(`[Amazon API] \u5F00\u59CB\u7B49\u5F85\u62A5\u544A\u5B8C\u6210: ${reportId}`);
        while (Date.now() - startTime < maxWaitMs) {
          const status = await this.getReportStatus(reportId);
          console.log(`[Amazon API] \u62A5\u544A\u72B6\u6001: ${status.status}, url: ${status.url ? "\u6709" : "\u65E0"}`);
          if (status.status === "COMPLETED" && status.url) {
            console.log(`[Amazon API] \u62A5\u544A\u5DF2\u5B8C\u6210\uFF0C\u5F00\u59CB\u4E0B\u8F7D...`);
            const data = await this.downloadReport(status.url);
            console.log(`[Amazon API] \u62A5\u544A\u4E0B\u8F7D\u5B8C\u6210\uFF0C\u6570\u636E\u6761\u6570: ${data?.length || 0}`);
            return data;
          }
          if (status.status === "FAILED") {
            console.error(`[Amazon API] \u62A5\u544A\u751F\u6210\u5931\u8D25`);
            throw new Error("Report generation failed");
          }
          console.log(`[Amazon API] \u62A5\u544A\u672A\u5B8C\u6210\uFF0C\u7B49\u5F855\u79D2\u540E\u91CD\u8BD5...`);
          await new Promise((resolve) => setTimeout(resolve, 5e3));
        }
        console.error(`[Amazon API] \u62A5\u544A\u751F\u6210\u8D85\u65F6`);
        throw new Error("Report generation timeout");
      }
      // ==================== Sponsored Brands API ====================
      /**
       * 获取SB广告活动列表
       * 注意：SB v4 API需要特定的Content-Type header
       */
      async listSbCampaigns() {
        const allCampaigns = [];
        let nextToken;
        let pageCount = 0;
        do {
          const body = { maxResults: 100 };
          if (nextToken) {
            body.nextToken = nextToken;
          }
          const response = await this.axiosInstance.post(
            "/sb/v4/campaigns/list",
            body,
            {
              headers: {
                "Content-Type": "application/vnd.sbcampaignresource.v4+json",
                "Accept": "application/vnd.sbcampaignresource.v4+json"
              }
            }
          );
          const campaigns6 = response.data.campaigns || [];
          if (pageCount === 0 && campaigns6.length > 0) {
            console.log("[SB API DEBUG] First campaign full structure:");
            console.log(JSON.stringify(campaigns6[0], null, 2));
            console.log("[SB API DEBUG] First campaign startDate:", campaigns6[0].startDate);
            console.log("[SB API DEBUG] First campaign keys:", Object.keys(campaigns6[0]));
            console.log("[SB API] \u9884\u7B97\u5B57\u6BB5\u68C0\u67E5:");
            console.log("  - budget:", campaigns6[0].budget);
            console.log("  - dailyBudget:", campaigns6[0].dailyBudget);
            console.log("  - state:", campaigns6[0].state);
            console.log("  - status:", campaigns6[0].status);
          }
          allCampaigns.push(...campaigns6);
          nextToken = response.data.nextToken;
          pageCount++;
          console.log(`[SB API] \u7B2C${pageCount}\u9875\u83B7\u53D6\u5230 ${campaigns6.length} \u4E2ASB\u5E7F\u544A\u6D3B\u52A8, \u603B\u8BA1: ${allCampaigns.length}`);
        } while (nextToken);
        console.log(`[SB API] \u5171\u83B7\u53D6\u5230 ${allCampaigns.length} \u4E2ASB\u5E7F\u544A\u6D3B\u52A8`);
        return allCampaigns;
      }
