    const conflicts = await getSyncConflicts(input.accountId, "pending");
    if (conflicts.length === 0) return { ignored: 0 };
    let ignored = 0;
    for (const conflict of conflicts) {
      await ignoreSyncConflict(conflict.id, ctx.user.id);
      ignored++;
    }
    return { ignored };
